"""ib_ar2.py — python wrapper for libib_ar2.so (2-rank all-reduce over native
InfiniBand on the ConnectX-3/mlx4 fabric).

Drop-in for cuda_communicator's DS4_IB_AR2 path; same stream-async design as
tbv_ar2 (stage copy -> doorbell -> GPU wait+add, CPU progress thread posts the
RDMA writes). The transport differences (LID addressing, active-MTU clamp,
HCA selection via DS4_IB_AR2_HCA) live entirely in the C library.
"""
import ctypes
import os

import torch

_LIB_PATHS = [
    os.path.join(os.path.dirname(os.path.abspath(__file__)), "libib_ar2.so"),
    "/opt/venv/lib64/python3.12/site-packages/libib_ar2.so",
]

BOX1_IP = os.environ.get("DS4_IB_AR2_IP", "192.168.100.1")
PORT = int(os.environ.get("DS4_IB_AR2_PORT", "18542"))  # 18515 v1, 18531 tbv2, 18541 odl2

_DTYPE = {torch.bfloat16: 0, torch.float16: 1, torch.float32: 2}


class IbAllReduce2:
    def __init__(self, rank: int, peer_ip: str = BOX1_IP, port: int = PORT):
        lib = None
        for p in _LIB_PATHS:
            if os.path.exists(p):
                lib = ctypes.CDLL(p)
                break
        if lib is None:
            raise RuntimeError("libib_ar2.so not found")
        lib.ibar2_init.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int]
        lib.ibar2_enqueue.argtypes = [ctypes.c_void_p, ctypes.c_void_p,
                                      ctypes.c_void_p, ctypes.c_uint32, ctypes.c_int]
        lib.ibar2_last_error.restype = ctypes.c_int
        lib.ibar2_max_bytes.restype = ctypes.c_uint32
        if lib.ibar2_init(rank, peer_ip.encode(), port) != 0:
            raise RuntimeError("ibar2_init failed")
        self._lib = lib
        self.max_bytes = lib.ibar2_max_bytes()

    def eligible(self, t: torch.Tensor) -> bool:
        return (
            t.is_cuda
            and t.is_contiguous()
            and t.dtype in _DTYPE
            and t.numel() * t.element_size() <= self.max_bytes
            and not torch.cuda.is_current_stream_capturing()
        )

    def all_reduce_out(self, inp: torch.Tensor, out: torch.Tensor) -> torch.Tensor:
        """Out-of-place SUM all-reduce: out = inp + peer(inp). Stream-async;
        downstream ops on the current stream see the result via stream order."""
        nbytes = inp.numel() * inp.element_size()
        # A previous round's latched error surfaces here (the enqueue itself is
        # fire-and-forget on the stream).
        if self._lib.ibar2_last_error():
            raise RuntimeError("ib_ar2: latched error from a prior round")
        stream = torch.cuda.current_stream().cuda_stream
        rc = self._lib.ibar2_enqueue(
            ctypes.c_void_p(stream),
            ctypes.c_void_p(out.data_ptr()),
            ctypes.c_void_p(inp.data_ptr()),
            nbytes, _DTYPE[inp.dtype])
        if rc != 0:
            raise RuntimeError(f"ibar2_enqueue failed: {rc}")
        return out
